-- TNP Travel Agency initial schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create type public.booking_status as enum ('pending','reviewing','awaiting_payment','confirmed','completed','cancelled','rejected');
create type public.payment_status as enum ('initiated','pending','succeeded','failed','cancelled','refunded','partially_refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role text not null default 'customer' check(role in ('customer','support','booking_manager','finance_manager','admin','super_admin')), created_at timestamptz not null default now());
create table public.services(id uuid primary key default gen_random_uuid(), name text not null unique, description text, active boolean not null default true, created_at timestamptz not null default now());
create table public.destinations(id uuid primary key default gen_random_uuid(), name text not null unique, country_code text, description text, active boolean not null default true);
create table public.bookings(id uuid primary key default gen_random_uuid(), reference text not null unique default ('TNP-'||upper(substr(encode(gen_random_bytes(6),'hex'),1,10))), customer_id uuid references auth.users(id) on delete set null, customer_name text not null, email text not null, phone text not null, service_type text not null, destination text, travel_date date, details text, status public.booking_status not null default 'pending', quoted_amount numeric(12,2), currency text not null default 'RWF', assigned_to uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.booking_history(id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id) on delete cascade, old_status public.booking_status, new_status public.booking_status not null, note text, changed_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id), customer_id uuid references auth.users(id), provider text not null, provider_reference text unique, amount numeric(12,2) not null check(amount>0), currency text not null, method text, status public.payment_status not null default 'initiated', checkout_url text, verified_at timestamptz, created_at timestamptz not null default now());
create table public.payment_events(id uuid primary key default gen_random_uuid(), payment_id uuid references public.payments(id), provider text not null, event_id text, event_type text, signature_valid boolean not null default false, payload jsonb not null default '{}', processed_at timestamptz, created_at timestamptz not null default now(), unique(provider,event_id));
create table public.refunds(id uuid primary key default gen_random_uuid(), payment_id uuid not null references public.payments(id), amount numeric(12,2) not null check(amount>0), reason text, provider_reference text, status text not null default 'requested', requested_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.documents(id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id) on delete cascade, owner_id uuid references auth.users(id), storage_path text not null, document_type text, created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), booking_id uuid references public.bookings(id), channel text not null, subject text, body text not null, sent_at timestamptz, created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity text, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create index bookings_created_idx on public.bookings(created_at desc); create index bookings_customer_idx on public.bookings(customer_id); create index payments_booking_idx on public.payments(booking_id); create index payments_status_idx on public.payments(status);
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('support','booking_manager','finance_manager','admin','super_admin')); $$;
create or replace function public.has_role(allowed text[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role=any(allowed)); $$;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create trigger bookings_touch before update on public.bookings for each row execute function public.touch_updated_at();
-- Public visitors may submit booking inquiries. Do not expose private booking rows to anon users.
alter table public.profiles enable row level security; alter table public.services enable row level security; alter table public.destinations enable row level security; alter table public.bookings enable row level security; alter table public.booking_history enable row level security; alter table public.payments enable row level security; alter table public.payment_events enable row level security; alter table public.refunds enable row level security; alter table public.documents enable row level security; alter table public.notifications enable row level security; alter table public.audit_logs enable row level security;
create policy "profiles own or staff read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_staff());
create policy "profile own update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "active services public read" on public.services for select to anon,authenticated using(active or public.is_staff());
create policy "staff manage services" on public.services for all to authenticated using(public.has_role(array['admin','super_admin'])) with check(public.has_role(array['admin','super_admin']));
create policy "active destinations public read" on public.destinations for select to anon,authenticated using(active or public.is_staff());
create policy "staff manage destinations" on public.destinations for all to authenticated using(public.has_role(array['admin','super_admin'])) with check(public.has_role(array['admin','super_admin']));
create policy "public create inquiry" on public.bookings for insert to anon,authenticated with check(status='pending' and customer_id is null);
create policy "customer read own bookings" on public.bookings for select to authenticated using(customer_id=auth.uid() or public.is_staff());
create policy "staff update bookings" on public.bookings for update to authenticated using(public.has_role(array['booking_manager','admin','super_admin','support'])) with check(public.has_role(array['booking_manager','admin','super_admin','support']));
create policy "history own or staff" on public.booking_history for select to authenticated using(public.is_staff() or exists(select 1 from public.bookings b where b.id=booking_id and b.customer_id=auth.uid()));
create policy "staff history insert" on public.booking_history for insert to authenticated with check(public.is_staff());
create policy "payments own or staff" on public.payments for select to authenticated using(public.is_staff() or customer_id=auth.uid());
create policy "staff manage payments" on public.payments for all to authenticated using(public.has_role(array['finance_manager','admin','super_admin'])) with check(public.has_role(array['finance_manager','admin','super_admin']));
create policy "events staff only" on public.payment_events for all to authenticated using(public.has_role(array['finance_manager','admin','super_admin'])) with check(public.has_role(array['finance_manager','admin','super_admin']));
create policy "refunds staff only" on public.refunds for all to authenticated using(public.has_role(array['finance_manager','admin','super_admin'])) with check(public.has_role(array['finance_manager','admin','super_admin']));
create policy "documents own or staff" on public.documents for select to authenticated using(owner_id=auth.uid() or public.is_staff());
create policy "documents own upload" on public.documents for insert to authenticated with check(owner_id=auth.uid());
create policy "notifications own or staff" on public.notifications for select to authenticated using(user_id=auth.uid() or public.is_staff());
create policy "staff manage notifications" on public.notifications for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "audit admin read" on public.audit_logs for select to authenticated using(public.has_role(array['admin','super_admin']));
insert into public.services(name,description) values ('Air ticketing','Flight booking inquiries and ticketing support'),('Visa assistance','Visa application guidance'),('Hotel booking','Hotel reservations'),('Car rental','Vehicle rental arrangements'),('Tours & trip plans','Tour packages and itinerary planning'),('Gorilla permits','Gorilla permit inquiries'),('Study & work abroad','Study and work opportunity guidance'),('Money transfer','Money transfer service inquiries') on conflict do nothing;
